UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_normalize_utf32(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored */
  if (options & (UTF8PROC_NLF2LS | UTF8PROC_NLF2PS | UTF8PROC_STRIPCC)) {
    utf8proc_ssize_t rpos;
    utf8proc_ssize_t wpos = 0;
    utf8proc_int32_t uc;
    for (rpos = 0; rpos < length; rpos++) {
      uc = buffer[rpos];
      if (uc == 0x000D && rpos < length-1 && buffer[rpos+1] == 0x000A) rpos++;
      if (uc == 0x000A || uc == 0x000D || uc == 0x0085 ||
          ((options & UTF8PROC_STRIPCC) && (uc == 0x000B || uc == 0x000C))) {
        if (options & UTF8PROC_NLF2LS) {
          if (options & UTF8PROC_NLF2PS) {
            buffer[wpos++] = 0x000A;
          } else {
            buffer[wpos++] = 0x2028;
          }
        } else {
          if (options & UTF8PROC_NLF2PS) {
            buffer[wpos++] = 0x2029;
          } else {
            buffer[wpos++] = 0x0020;
          }
        }
      } else if ((options & UTF8PROC_STRIPCC) &&
          (uc < 0x0020 || (uc >= 0x007F && uc < 0x00A0))) {
        if (uc == 0x0009) buffer[wpos++] = 0x0020;
      } else {
        buffer[wpos++] = uc;
      }
    }
    length = wpos;
  }

UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_normalize_utf32(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored */
  if (options & (UTF8PROC_NLF2LS | UTF8PROC_NLF2PS | UTF8PROC_STRIPCC)) {
    utf8proc_ssize_t rpos;
    utf8proc_ssize_t wpos = 0;
    utf8proc_int32_t uc;
    for (rpos = 0; rpos < length; rpos++) {
      uc = buffer[rpos];
      if (uc == 0x000D && rpos < length-1 && buffer[rpos+1] == 0x000A) rpos++;
      if (uc == 0x000A || uc == 0x000D || uc == 0x0085 ||
          ((options & UTF8PROC_STRIPCC) && (uc == 0x000B || uc == 0x000C))) {
        if (options & UTF8PROC_NLF2LS) {
          if (options & UTF8PROC_NLF2PS) {
            buffer[wpos++] = 0x000A;
          } else {
            buffer[wpos++] = 0x2028;
          }
        } else {
          if (options & UTF8PROC_NLF2PS) {
            buffer[wpos++] = 0x2029;
          } else {
            buffer[wpos++] = 0x0020;
          }
        }
      } else if ((options & UTF8PROC_STRIPCC) &&
          /* uc < 0 is a grapheme-break sentinel from UTF8PROC_CHARBOUND,
             not a control character, so keep it */
          ((uc >= 0 && uc < 0x0020) || (uc >= 0x007F && uc < 0x00A0))) {
        if (uc == 0x0009) buffer[wpos++] = 0x0020;
        /* a removed control character is a grapheme of its own, so also
           drop the boundary sentinel that UTF8PROC_CHARBOUND put before it */
        else if ((options & UTF8PROC_CHARBOUND) && wpos > 0 && buffer[wpos-1] == -1) wpos--;
      } else {
        buffer[wpos++] = uc;
      }
    }
    length = wpos;
  }

if (options & UTF8PROC_CHARBOUND) {
  utf8proc_bool boundary;
  boundary = grapheme_break_extended(0, property->boundclass, 0, property->indic_conjunct_break,
                                     last_boundclass);
  if (boundary) {
    if (bufsize >= 1) dst[0] = -1; /* sentinel value for grapheme break */
    if (bufsize >= 2) dst[1] = uc;
    return 2;
  }
}
if (bufsize >= 1) *dst = uc;
return 1;

UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_map_custom(
  const utf8proc_uint8_t *str, utf8proc_ssize_t strlen, utf8proc_uint8_t **dstptr, unsigned int options,
  utf8proc_custom_func custom_func, void *custom_data
) {
  utf8proc_int32_t *buffer;
  utf8proc_ssize_t result;
  utf8proc_ssize_t bufsize;
  *dstptr = NULL;
  bufsize = utf8proc_decompose_custom(str, strlen, NULL, 0, options, custom_func, custom_data);
  if (bufsize < 0) return bufsize;
  buffer = (utf8proc_int32_t *) malloc(((utf8proc_size_t)bufsize) * sizeof(utf8proc_int32_t) + 1);
  if (!buffer) return UTF8PROC_ERROR_NOMEM;
  result = utf8proc_decompose_custom(str, strlen, buffer, bufsize, options, custom_func, custom_data);
  if (result < 0) {
    free(buffer);
    return result;
  }
  /* a custom_func that returns different results across the two decompose
     passes can make the second pass longer than the buffer we sized from the
     first; reencode would then read and write past the allocation, so bail
     out instead of corrupting the heap */
  if (result > bufsize) {
    free(buffer);
    return UTF8PROC_ERROR_OVERFLOW;
  }
  result = utf8proc_reencode(buffer, result, options);
  if (result < 0) {
    free(buffer);
    return result;
  }
  {
    utf8proc_int32_t *newptr;
    newptr = (utf8proc_int32_t *) realloc(buffer, (size_t)result+1);
    if (newptr) buffer = newptr;
  }
  *dstptr = (utf8proc_uint8_t *)buffer;
  return result;

for (i = 0; i < sizeof(input) / sizeof(input[0]); i++) {
    utf8proc_ssize_t glen;
    utf8proc_uint8_t *g;
    glen = utf8proc_map(input[i], 0, &g, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND | UTF8PROC_STRIPCC);
    check(glen == (utf8proc_ssize_t)strlen((char*)output[i]), "CHARBOUND|STRIPCC returned wrong length in case %zu", i);
    check(!strcmp((char*)g, (char*)output[i]), "CHARBOUND|STRIPCC dropped grapheme markers in case %zu", i);
    utf8proc_free(g);
    glen = utf8proc_map(input[i], 0, &g, UTF8PROC_NULLTERM | UTF8PROC_STRIPCC);
    check(glen == (utf8proc_ssize_t)strlen(plain[i]), "STRIPCC returned wrong length in case %zu", i);
    check(!strcmp((char*)g, plain[i]), "STRIPCC changed output in case %zu", i);
    {
        utf8proc_uint8_t *separate, *combined;
        utf8proc_ssize_t separate_len, combined_len;
        separate_len = utf8proc_map(g, 0, &separate, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND);
        combined_len = utf8proc_map(input[i], 0, &combined, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND | UTF8PROC_STRIPCC);
        check(separate_len >= 0 && combined_len >= 0, "two-step mapping failed in case %zu", i);
        check(separate_len == combined_len, "two-step mapping returned different length in case %zu", i);
        check(!memcmp(separate, combined, (size_t)combined_len + 1), "two-step mapping differs from combined flags in case %zu", i);

utf8proc_int32_t *copy = size >= 4 ? malloc(size) : NULL;

if(copy)
{
    size /= 4; /* number of utf8proc_int32_t code points that fit in copy */

    options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = UTF8PROC_STRIPCC | UTF8PROC_NLF2PS;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = UTF8PROC_STRIPCC;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = UTF8PROC_LUMP;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = 0;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    free(copy);
}

utf8proc_free(utf8proc_NFD(data));
utf8proc_free(utf8proc_NFC(data));
utf8proc_free(utf8proc_NFKD(data));
utf8proc_free(utf8proc_NFKC(data));
utf8proc_free(utf8proc_NFKC_Casefold(data));

utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_STRIPNA);
utf8proc_free(str);

utf8proc_map(data, len, &str, UTF8PROC_LUMP | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS);
utf8proc_free(str);

utf8proc_map(data, len, &str, UTF8PROC_COMPOSE | UTF8PROC_STRIPMARK);
utf8proc_free(str);

utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_DECOMPOSE);
utf8proc_free(str);

utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_COMPOSE);
utf8proc_free(str);
